# Expected values generated by test/pandas/gen_expected.py (pandas 3.1.1).

import numpy as np
import pandas as pd
import hashlib

def make_F(n: int, m: int, seed: int = 12345):
    F = np.empty((n, m))
    s = seed
    for i in range(n):
        for j in range(m):
            s = (s * 1103515245 + 12345) % 2147483648
            F[i, j] = float(s % 20001 - 10000) * 0.000123 * float(j + 1)
    return F

def make_y(n: int):
    return np.array([(i * 7 % 5) % 2 for i in range(n)])

def _r(x) -> str:
    if isinstance(x, pd.Scalar):
        return repr(x.f) if x.kind == 0 else (repr(x.s) if x.kind == 3 else str(x))
    elif isinstance(x, float) or isinstance(x, str):
        return repr(x)
    else:
        return str(x)

@test
def test_groupby():
    F = make_F(40, 8)
    y = make_y(40)
    df = pd.DataFrame(F, columns=[f"ch{i}" for i in range(F.shape[1])])
    df["label"] = y
    g = df.groupby("label").mean()
    d = df.drop(columns="label").describe()
    c = df.drop(columns="label").corr()
    csv = df.to_csv(float_format="%.17g")

    F2 = make_F(13, 4, seed=777)
    F2[3, 1] = float("nan")
    F2[7, 2] = float("nan")
    d2 = pd.DataFrame(F2, columns=["a", "b", "c", "d"])
    d2["k"] = np.array([i % 3 for i in range(13)], dtype=int)

    assert d2.groupby("k").sum().to_csv() == 'k,a,b,c,d\n0,1.4344260000000002,1.9694760000000002,6.717276,-8.952924\n1,-0.8844930000000001,3.5642940000000003,-4.067487,-2.652864\n2,-0.6110640000000002,-6.057012,5.146812000000001,-5.377068\n'
    assert d2.groupby("k").mean().to_csv() == 'k,a,b,c,d\n0,0.28688520000000006,0.49236900000000006,1.3434552,-1.7905848\n1,-0.22112325000000002,0.8910735000000001,-1.355829,-0.663216\n2,-0.15276600000000004,-1.514253,1.2867030000000002,-1.344267\n'
    assert d2.groupby("k").std().to_csv() == 'k,a,b,c,d\n0,0.6174523773832279,1.7917338748742795,2.427449138119108,1.727936872067727\n1,1.002931100673546,0.5089158505931999,1.1479824452764946,2.547649542391575\n2,1.0108793893427643,0.9031164584105419,2.162870828871202,2.0928400951749757\n'
    assert d2.groupby("k").var().to_csv() == 'k,a,b,c,d\n0,0.38124743833620006,3.2103102783720003,5.8925093181552,2.9857658338512003\n1,1.0058707926982502,0.2589953429850001,1.317863694663,6.490518190848001\n2,1.021877139798,0.815619337452,4.678010222382,4.379979663972001\n'
    assert d2.groupby("k").min().to_csv() == 'k,a,b,c,d\n0,-0.567153,-1.890756,-2.8844730000000003,-3.556668\n1,-1.149804,0.42410400000000004,-2.021751,-3.411528\n2,-1.040334,-2.3862,-1.584117,-3.5827440000000004\n'
    assert d2.groupby("k").max().to_csv() == 'k,a,b,c,d\n0,1.084122,2.375868,3.3291180000000002,0.507252\n1,1.193346,1.4937120000000002,-0.030258000000000004,2.057544\n2,0.908355,-0.31881600000000004,3.46491,0.550056\n'
    assert d2.groupby("k").count().to_csv() == 'k,a,b,c,d\n0,5,4,5,5\n1,4,4,3,4\n2,4,4,4,4\n'
    assert d2.groupby("k").size().to_csv() == 'k,0\n0,5\n1,4\n2,4\n'
    assert d2.groupby("k").median().to_csv() == 'k,a,b,c,d\n0,0.35559300000000005,0.7421820000000001,2.198133,-2.4816480000000003\n1,-0.4640175,0.823239,-2.015478,-0.6494400000000001\n2,-0.23954250000000005,-1.675998,1.6330095,-1.17219\n'
    assert d2.groupby("k").agg("sum").to_csv() == 'k,a,b,c,d\n0,1.4344260000000002,1.9694760000000002,6.717276,-8.952924\n1,-0.8844930000000001,3.5642940000000003,-4.067487,-2.652864\n2,-0.6110640000000002,-6.057012,5.146812000000001,-5.377068\n'
    assert d2.groupby("k")["a"].mean().to_csv() == 'k,a\n0,0.28688520000000006\n1,-0.22112325000000002\n2,-0.15276600000000004\n'
    s3 = pd.DataFrame({"name": pd.Series(["b", "a", "c", "a", "b", "b"]), "v": pd.Series([1, 2, 3, 4, 5, 6]), "w": pd.Series([0.5, 1.5, 2.5, 3.5, 4.5, 5.5])})
    assert s3.groupby("name").sum().to_csv() == 'name,v,w\na,6,5.0\nb,12,10.5\nc,3,2.5\n'
    assert s3.groupby("name").mean().to_csv() == 'name,v,w\na,3.0,2.5\nb,4.0,3.5\nc,3.0,2.5\n'
    assert s3.groupby("name", sort=False).sum().to_csv() == 'name,v,w\nb,12,10.5\na,6,5.0\nc,3,2.5\n'
    assert s3["name"].value_counts().to_csv() == 'name,count\nb,3\na,2\nc,1\n'
    assert s3["name"].value_counts(normalize=True).to_csv() == 'name,proportion\nb,0.5\na,0.3333333333333333\nc,0.16666666666666666\n'

    print("test_groupby: ok")

test_groupby()
